  -webkit-border-radius: 50% !important;
  border-radius: 50% !important;
  -moz-box-shadow: 0 0 4px #333;
  -webkit-box-shadow: 0 0 4px #333;
  box-shadow: 0 0 4px #333;
  width: 72px;
  height: 72px;
  border: none;
}

.BALaunchImage {
  height: auto;
  width: auto;
  top: 15px;
  left: 12px;
  position: relative;
  float: none;
}

.BALaunchPad {
  padding: 0;
  border-radius: 50% !important;
  box-shadow: 0 0 4px #333;
  width: 72px;
  height: 72px;
}


.__ba_hidden {
  opacity: 0;
  cursor: default !important;
}

#__ba_panel {
  border: 0 !important;
  text-align: left;
}

#__ba_panel._launchpad {
  position: fixed !important;
  z-index: 100000 !important;
  height: 72px !important;
  width: 72px !important;
}

#_ba_corner {
  width: 72px !important;
  height: 72px !important;
  padding: 0 !important;
  -moz-border-radius: 50% !important;
  -webkit-border-radius: 50% !important;
  border-radius: 50% !important;
  -moz-box-shadow: 0 0 4px #333 !important;
  -webkit-box-shadow: 0 0 4px #333 !important;
  box-shadow: 0 0 4px #333 !important;
}

#_ba_corner a {
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  text-decoration: none !important;
  margin: 0 !important;
  padding: 0 !important;
  background: none !important;
}

#_ba_corner a::before {
  background: none;
}

#_ba_corner img {
  height: auto !important;
  width: auto !important;
  top: 15px !important;
  left: 12px !important;
  position: relative !important;
  padding: 0 !important;
  margin: 0 !important;
  float: none !important;
}

.imgDiv {
  border: 0;
  text-align: left;
  width: 120px;
  height: 52px;
}

.imgOnlyDiv {
  border: 0;
  text-align: left;
  width: fit-content;
  padding: 0;
  background: transparent;
}

.customImg {
  outline: none !important;
}

.pillButton:focus>.outerSpan {
  outline: -webkit-focus-ring-color auto 5px;
}

.outerSpan {
  outline: none !important;
  display: inline-block;
  width: fit-content;
  height: 50px;
  min-width: 135px;
}

.pillButton {
  background-color: #cc4518;
  border-radius: 30px;
  color: transparent;
  border: 1px solid transparent;
  position: relative;
  display: inline-block;
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  color: #cc4518;
  height: 50px;
  min-width: 135px;
  margin: 0 auto;
  line-height: 50px;
  text-align: center;
  border-radius: 30px;
  border: 1px solid transparent;
  text-decoration: none;
  transition: all ease-in-out .1s;
  cursor: pointer;
  color: #FFF;
}

.launchIconLeft {
  top: 2px;
  height: 14px;
  margin: 0 4px 0 0;
  background-size: 20px 14px;
  background-image: url(https://www.browsealoud.com/modules/3.10.0/efbeeb9c3e34cceebfb6.png);
  position: relative;
  display: inline-block;
  width: 20px;
  background-repeat: round;
  outline: none !important;
}

.launchTextSpan {
  background-color: #cc4518;
  border-radius: 30px;
  color: transparent;
  border: 1px solid transparent;
  color: #FFF;
  outline: none !important;
}


.launchIconRight {
  top: 5px;
  height: 20px;
  margin: 0 0 0 5px;
  background-size: 20px 20px;
  background-image: url(https://www.browsealoud.com/modules/3.10.0/02135c6095419d11dcdc.png);
  position: relative;
  display: inline-block;
  width: 20px;
  background-repeat: round;
  outline: none !important;
}

.textDiv {
  border: 0;
  background-color: transparent;
  text-align: left;
  cursor: pointer;
  padding: 0;
}

.customText {
  outline: none !important;
}

.baButton:focus>.imgStyle {
  outline: -webkit-focus-ring-color auto 5px;
}

.baButton {
  margin: 0;
  background: 0 0;
  width: fit-content;
  height: 100%;
  display: block;
  border: 0;
  background-color: transparent;
  padding: 0;
}

.imgStyle {
  border: 0;
  padding: 0;
  margin: 0;
  background: 0 0;
  vertical-align: middle;
  outline: none !important;
}

.BALaunchImage {
  height: 48px;
  width: 48px;
  left: 0px;
  top: 6px;
  display: inline-block;
  background-repeat: no-repeat;
  outline: none !important;
}

#__ba_panel.topRight {
  top: 7px;
}

#__ba_panel.topLeft {
